const front = $('Vagas Frontend BR').all().map(x => x.json).flatMap(x => Array.isArray(x) ? x : [x]);
const back = $('Vagas Backend BR').all().map(x => x.json).flatMap(x => Array.isArray(x) ? x : [x]);
const remoteRaw = $('Vagas Remotas Himalayas').all().map(x => x.json).flatMap(x => Array.isArray(x) ? x : [x]);
const adzunaRaw = $('Vagas Adzuna').all().map(x => x.json).flatMap(x => Array.isArray(x.results) ? x.results : (Array.isArray(x) ? x : [x]));
const joobleRaw = $('Vagas Jooble').all().map(x => x.json).flatMap(x => Array.isArray(x.jobs) ? x.jobs : (Array.isArray(x) ? x : [x]));
const remoteJobs = Array.isArray(remoteRaw) && remoteRaw[0] && Array.isArray(remoteRaw[0].jobs) ? remoteRaw[0].jobs : [];
const nowIso = new Date().toISOString();
const maxHistoric = 400;
const sourceNames = ['Frontend BR', 'Backend BR', 'Himalayas', 'Adzuna', 'Jooble'];
function textValue(v) { return String(v ?? '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim(); }
function normalizeUrl(raw) {
  if (!raw) return '';
  const value = String(raw).trim();
  if (!/^https?:\/\//i.test(value)) return value;
  try {
    const url = new URL(value);
    url.hash = '';
    const params = new URLSearchParams(url.search);
    const tracking = new Set(['utm_source','utm_medium','utm_campaign','utm_term','utm_content','utm_id','gclid','fbclid','mc_cid','mc_eid']);
    for (const key of [...params.keys()]) {
      if (tracking.has(String(key).toLowerCase())) params.delete(key);
    }
    url.search = params.toString();
    return String(url).replace(/[?#]+$/, '');
  } catch (e) {
    return value.replace(/[?&](?:utm_[^&]+|gclid|fbclid|mc_cid|mc_eid)=[^&]+/gi, '').replace(/&&+/g, '&').replace(/[?&]$/, '');
  }
}
function normalizeCompany(value) {
  return String(value || '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\b(?:ltda|ltda\.|sa|s\.a\.|s\/a|inc|corp|company|consultoria|brasil|do brasil)\b/gi, '')
    .replace(/[^A-Za-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}
function normalizeRole(value) {
  return String(value || '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\b(full[\s-]?stack)\b/gi, 'fullstack')
    .replace(/\b(front[\s-]?end)\b/gi, 'frontend')
    .replace(/\b(back[\s-]?end)\b/gi, 'backend')
    .replace(/\b(junior|júnior|jr|estagi[oá]rio|est[aá]gio|intern(ship)?|trainee|entry[\s-]?level)\b/gi, '')
    .replace(/[^A-Za-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}
function normalizeItem(item, source) {
  if (!item || !item.id) return null;
  const url = normalizeUrl(item.link || item.url || item.redirect_url || item.applicationLink || item.html_url || '');
  const company = String(item.company || item.empresa || item.companyName || 'Ver anúncio');
  const cargo = String(item.title || item.cargo || item.job_title || '');
  const description = String(item.description || item.descricao || item.snippet || '');
  return {
    id: `${source.toLowerCase().replace(/\W+/g, '-')}-${String(item.id || url || cargo || company)}`.slice(0, 180),
    cargo: cargo || 'Cargo não informado',
    empresa: company || 'Ver anúncio',
    nivel: /est[aá]gio|intern|aprendiz|trainee/i.test(`${cargo} ${description}`) ? 'Estágio' : /junior|júnior|jr/i.test(`${cargo} ${description}`) ? 'Júnior' : 'Não informada',
    modalidade: /remot|home\.?office/i.test(`${cargo} ${description}`) ? 'Remoto' : (/h[ií]brid/i.test(`${cargo} ${description}`) ? 'Híbrido' : 'Não informada'),
    local: item.location || item.local || 'Brasil / ver anúncio',
    descricao: description.slice(0, 500),
    publicadoEm: item.created || item.created_at || item.date || item.publishedAt || '',
    fonte: source,
    link: url || item.link || item.url || item.redirect_url || item.applicationLink || '',
    capturadoEm: nowIso,
    primeiraIdentificacao: nowIso,
    ultimaIdentificacao: nowIso,
    statusIdentificacao: 'nova',
    urlNormalizada: url,
    empresaNormalizada: normalizeCompany(company),
    cargoNormalizado: normalizeRole(cargo),
    fontesAlternativas: [source] 
  };
}
const incoming = [
  ...front.filter(Boolean).map(item => normalizeItem(item, 'Frontend BR')),
  ...back.filter(Boolean).map(item => normalizeItem(item, 'Backend BR')),
  ...remoteJobs.filter(Boolean).map(item => normalizeItem({ ...item, id: item.id || item.guid || item.applicationLink || item.title, link: item.applicationLink || item.link || item.url }, 'Himalayas')),
  ...adzunaRaw.filter(Boolean).map(item => normalizeItem({ ...item, id: item.id || item.redirect_url || item.title, link: item.redirect_url || item.redirect_url || item.url, company: item.company && item.company.display_name ? item.company.display_name : item.company, title: item.title || item.cargo, description: item.description || item.snippet }, 'Adzuna')),
  ...joobleRaw.filter(Boolean).map(item => normalizeItem({ ...item, id: item.id || item.link || item.title, link: item.link || item.url, company: item.company, title: item.title || item.job_title, description: item.snippet || item.description, location: item.location || item.location || 'Brasil' }, 'Jooble'))
].filter(Boolean);
const githubFile = $input.first().json;
if (!githubFile || !githubFile.sha || !githubFile.content) { throw new Error('Arquivo data/vagas.json não encontrado.'); }
const existingJson = JSON.parse(Buffer.from(githubFile.content, 'base64').toString('utf8'));
const current = Array.isArray(existingJson.vagas) ? existingJson.vagas : [];
const existingById = new Map(current.map(v => [v.id, v]));
const urlIndex = new Map();
for (const item of current) {
  const url = normalizeUrl(item.link || item.url || item.html_url || item.applicationLink || '');
  if (url) urlIndex.set(url, item);
}
const merged = new Map();
for (const item of current) {
  if (item && item.id) {
    const clone = { ...item };
    clone.urlNormalizada = normalizeUrl(item.link || item.url || item.html_url || item.applicationLink || '');
    clone.empresaNormalizada = normalizeCompany(item.empresa || '');
    clone.cargoNormalizado = normalizeRole(item.cargo || '');
    clone.fontesAlternativas = Array.isArray(item.fontesAlternativas) ? item.fontesAlternativas : [item.fonte].filter(Boolean);
    clone.primeiraIdentificacao = clone.primeiraIdentificacao || clone.capturadoEm || nowIso;
    clone.ultimaIdentificacao = clone.ultimaIdentificacao || clone.primeiraIdentificacao || nowIso;
    merged.set(item.id, clone);
  }
}
for (const item of incoming) {
  const existing = existingById.get(item.id);
  const url = item.urlNormalizada || normalizeUrl(item.link || '');
  const byUrl = url ? urlIndex.get(url) : null;
  const base = existing || byUrl || null;
  if (base) {
    const mergedItem = { ...base, ...item };
    if (!mergedItem.primeiraIdentificacao) mergedItem.primeiraIdentificacao = base.capturadoEm || nowIso;
    mergedItem.ultimaIdentificacao = nowIso;
    mergedItem.fontesAlternativas = Array.from(new Set([...(Array.isArray(base.fontesAlternativas) ? base.fontesAlternativas : []), ...(Array.isArray(item.fontesAlternativas) ? item.fontesAlternativas : []), base.fonte, item.fonte].filter(Boolean)));
    merged.set(base.id, mergedItem);
  } else {
    merged.set(item.id, item);
  }
}
const proposal = Array.from(merged.values())
  .filter(Boolean)
  .map(v => ({ ...v, urlNormalizada: normalizeUrl(v.link || v.url || v.html_url || v.applicationLink || ''), empresaNormalizada: normalizeCompany(v.empresa || ''), cargoNormalizado: normalizeRole(v.cargo || '') }))
  .sort((a, b) => new Date(b.ultimaIdentificacao || b.publicadoEm || b.capturadoEm || 0).getTime() - new Date(a.ultimaIdentificacao || a.publicadoEm || a.capturadoEm || 0).getTime())
  .slice(0, maxHistoric);
const comparableCurrent = current.map(item => ({ ...item, link: normalizeUrl(item.link || item.url || item.html_url || item.applicationLink || ''), urlNormalizada: normalizeUrl(item.link || item.url || item.html_url || item.applicationLink || '') }));
const comparableProposal = proposal.map(item => ({ ...item, link: normalizeUrl(item.link || item.url || item.html_url || item.applicationLink || ''), urlNormalizada: normalizeUrl(item.link || item.url || item.html_url || item.applicationLink || '') }));
const changedRelevant = JSON.stringify(comparableCurrent) !== JSON.stringify(comparableProposal);
const payload = {
  atualizadoEm: nowIso,
  total: proposal.length,
  vagas: proposal,
  ultimaSincronizacao: nowIso,
  ultimaSincronizacaoCompleta: nowIso,
  ultimaSincronizacaoParcial: null,
  limiteHistorico: maxHistoric,
  historicoPreservado: true,
  novasNaExecucao: proposal.filter(v => v.statusIdentificacao === 'nova').length,
  ultimaConsultaBemSucedida: { 'Frontend BR': nowIso, 'Backend BR': nowIso, 'Himalayas': nowIso, 'Adzuna': nowIso, 'Jooble': nowIso }
};
const shouldPublish = changedRelevant && proposal.length > 0;
return [{
  json: {
    changed: shouldPublish,
    relevantChange: changedRelevant,
    total: proposal.length,
    novos: payload.novasNaExecucao,
    sha: githubFile.sha,
    content: shouldPublish ? Buffer.from(JSON.stringify(payload, null, 2) + '\n', 'utf8').toString('base64') : null,
    preserveHistory: true
  }
}];

const status = $input.first().json.statusCode;
const body = $input.first().json.body || {};
const message = body && body.message ? String(body.message) : '';
const conflict = status === 409 || status === 422;
return [{ json: { statusCode: status, conflict, message, shouldRetry: conflict, publicationAttempted: true } }];
